/*
 * Narration player for pre-recorded MP3 guides (generated by tools/make_audio.py).
 *
 * Markup:
 *   <div class="listen" data-audio="../audio/page.mp3" data-audio-title="…" data-audio-target="#story">
 *     <div class="listen-row">
 *       <button data-audio-play>…</button> <button data-audio-rate>1×</button> <button data-audio-stop>■</button>
 *     </div>
 *     <div class="listen-progress"><input type="range" data-audio-seek> <span data-audio-time></span></div>
 *   </div>
 *
 * page.json next to the MP3 holds the start time (seconds) of each h2/p block in the
 * target, so the paragraph being read can be highlighted.
 */
(function () {
  const box = document.querySelector("[data-audio]");
  if (!box) return;

  const src = box.dataset.audio;
  const playBtn = box.querySelector("[data-audio-play]");
  const stopBtn = box.querySelector("[data-audio-stop]");
  const rateBtn = box.querySelector("[data-audio-rate]");
  const seek = box.querySelector("[data-audio-seek]");
  const time = box.querySelector("[data-audio-time]");
  const blocks = Array.from(document.querySelectorAll(box.dataset.audioTarget + " h2, " + box.dataset.audioTarget + " p"));

  const audio = new Audio(src);
  audio.preload = "metadata";
  audio.addEventListener("error", () => { if (audio.getAttribute("src")) setUnavailable(); });

  // The .json is written together with the MP3, so a missing .json means the narration
  // hasn't been generated yet: show the player as "coming soon".
  let starts = [];
  let unavailable = false;
  fetch(src.replace(/\.mp3$/, ".json"))
    .then((r) => (r.ok ? r.json() : null))
    .then((data) => {
      if (!data) return setUnavailable();
      if (data.starts.length === blocks.length) starts = data.starts;
    })
    .catch(setUnavailable);

  function setUnavailable() {
    unavailable = true;
    audio.removeAttribute("src");
    playBtn.disabled = true;
    playBtn.innerHTML = "🎧&nbsp; Аудио скоро появится";
    rateBtn.hidden = true;
    stopBtn.hidden = true;
    box.querySelector(".listen-progress").hidden = true;
  }

  const RATES = [1, 1.25, 1.5, 0.75];
  let rateIdx = 0;
  let current = -1;

  function fmt(s) {
    s = Math.max(0, Math.floor(s || 0));
    return Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0");
  }

  function render() {
    if (unavailable) return;
    const playing = !audio.paused;
    playBtn.innerHTML = playing ? "❚❚&nbsp; Пауза" : audio.currentTime > 0 ? "▶&nbsp; Продолжить" : "▶&nbsp; Слушать рассказ";
    stopBtn.hidden = !playing && audio.currentTime === 0;
  }

  function updateProgress() {
    const d = audio.duration || 0;
    seek.max = d || 100;
    seek.value = audio.currentTime;
    time.textContent = fmt(audio.currentTime) + " / " + fmt(d);
    seek.style.setProperty("--pct", d ? (audio.currentTime / d) * 100 + "%" : "0%");
  }

  function highlight() {
    if (!starts.length) return;
    let i = -1;
    if (!audio.paused || audio.currentTime > 0) {
      for (let k = 0; k < starts.length; k++) if (audio.currentTime >= starts[k]) i = k;
    }
    if (i === current) return;
    current = i;
    blocks.forEach((b, k) => b.classList.toggle("reading", k === i));
    if (i >= 0 && !audio.paused) scrollIntoViewIfNeeded(blocks[i]);
  }

  // Keep the paragraph below the sticky top bar + player (their height grows with text size).
  function scrollIntoViewIfNeeded(block) {
    const bar = box.getBoundingClientRect();
    const offset = Math.max(bar.bottom, 72 + bar.height) + 12;
    const r = block.getBoundingClientRect();
    if (r.top < offset || r.bottom > window.innerHeight) {
      window.scrollTo({ top: window.scrollY + r.top - offset, behavior: "smooth" });
    }
  }

  playBtn.addEventListener("click", () => {
    if (audio.paused) audio.play();
    else audio.pause();
  });

  stopBtn.addEventListener("click", () => {
    audio.pause();
    audio.currentTime = 0;
    render();
    highlight();
  });

  rateBtn.addEventListener("click", () => {
    rateIdx = (rateIdx + 1) % RATES.length;
    audio.playbackRate = RATES[rateIdx];
    rateBtn.textContent = String(RATES[rateIdx]).replace(".", ",") + "×";
  });

  seek.addEventListener("input", () => {
    audio.currentTime = Number(seek.value);
    updateProgress();
    highlight();
  });

  audio.addEventListener("play", render);
  audio.addEventListener("pause", render);
  audio.addEventListener("loadedmetadata", updateProgress);
  audio.addEventListener("timeupdate", () => {
    updateProgress();
    highlight();
  });
  audio.addEventListener("ended", () => {
    audio.currentTime = 0;
    render();
    highlight();
  });

  // Title, artwork and play/pause on the Android lock screen and notification shade.
  if ("mediaSession" in navigator) {
    const img = document.querySelector(".photo img");
    navigator.mediaSession.metadata = new MediaMetadata({
      title: box.dataset.audioTitle || document.title,
      artist: document.title.split(" — ").pop(),  // site name: titles are "Page — Site name"
      artwork: img ? [{ src: img.src, sizes: "960x960", type: "image/jpeg" }] : [],
    });
    navigator.mediaSession.setActionHandler("play", () => audio.play());
    navigator.mediaSession.setActionHandler("pause", () => audio.pause());
    navigator.mediaSession.setActionHandler("seekbackward", () => { audio.currentTime -= 10; });
    navigator.mediaSession.setActionHandler("seekforward", () => { audio.currentTime += 10; });
  }

  render();
  updateProgress();
})();
